void format_connection_address(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    char ip_str[INET6_ADDRSTRLEN] = "";
    const char *protocol = (c->transport == socks_transport_TCP) ? "tcp" : "udp";
    int port = 0;

    switch (af) {
        case AF_INET: {
            struct sockaddr_in *sin = (struct sockaddr_in *)sock_addr;
            inet_ntop(AF_INET, &(sin->sin_addr), ip_str, INET6_ADDRSTRLEN);
            port = ntohs(sin->sin_port);
            break;
        }
        case AF_INET6: {
            struct sockaddr_in6 *sin6 = (struct sockaddr_in6 *)sock_addr;
            inet_ntop(AF_INET6, &(sin6->sin6_addr), ip_str, INET6_ADDRSTRLEN);
            port = ntohs(sin6->sin6_port);
            break;
        }
        case AF_UNIX: {
            struct sockaddr_un *sun = (struct sockaddr_un *)sock_addr;
            strncpy(ip_str, sun->sun_path, sizeof(ip_str) - 1);
            ip_str[sizeof(ip_str) - 1] = '\0';
            break;
        }
        default:
            break;
    }

    if (strlen(ip_str) == 0) {
        strcpy(ip_str, "<unknown>");
    }

    if (port != 0) {
        snprintf(addr, INET6_ADDRSTRLEN + 6, "%s://%s:%d", protocol, ip_str, port);
    } else {
        snprintf(addr, INET6_ADDRSTRLEN + 6, "%s://%s", protocol, ip_str);
    }
}

void format_socket_address(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    const char *protocol = (c->transport == USE_UDP) ? "UDP" : "TCP";
    char address[NI_MAXHOST] = "";
    char port[NI_MAXSERV] = "";
    socklen_t addr_len = 0;

    if (af == AF_INET || af == AF_INET6) {
        void *ip;
        uint16_t port_num;

        if (af == AF_INET) {
            struct sockaddr_in *sa_in = (struct sockaddr_in *)sock_addr;
            ip = &(sa_in->sin_addr);
            port_num = ntohs(sa_in->sin_port);
            addr_len = sizeof(struct sockaddr_in);
        } else {
            struct sockaddr_in6 *sa_in6 = (struct sockaddr_in6 *)sock_addr;
            ip = &(sa_in6->sin6_addr);
            port_num = ntohs(sa_in6->sin6_port);
            addr_len = sizeof(struct sockaddr_in6);
        }

        inet_ntop(af, ip, address, sizeof(address));
        snprintf(port, sizeof(port), "%d", port_num);
    } else if (af == AF_UNIX) {
        struct sockaddr_un *sa_un = (struct sockaddr_un *)sock_addr;
        snprintf(address, NI_MAXHOST, "%s", sa_un->sun_path);
    }

    if (strlen(address) == 0) {
        snprintf(address, sizeof(address), "%s", "<unknown>");
    }

    if (strlen(port) > 0) {
        snprintf(addr, NI_MAXHOST + NI_MAXSERV, "%s://%s:%s", protocol, address, port);
    } else {
        snprintf(addr, NI_MAXHOST, "%s://%s", protocol, address);
    }
}

void format_connection_address(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    char ip_str[INET6_ADDRSTRLEN];
    int port = 0;
    socklen_t addr_len = 0;

    if (af == AF_INET || af == AF_INET6) {
        if (af == AF_INET) {
            addr_len = sizeof(struct sockaddr_in);
        } else {
            addr_len = sizeof(struct sockaddr_in6);
        }

        if (inet_ntop(af, get_in_addr(sock_addr, af), ip_str, INET6_ADDRSTRLEN) == NULL) {
            strncpy(ip_str, "unknown", INET6_ADDRSTRLEN);
        }

        if (c && c->transport == TRANSPORT_TCP) {
            if (af == AF_INET) {
                port = ntohs(((struct sockaddr_in *)sock_addr)->sin_port);
            } else {
                port = ntohs(((struct sockaddr_in6 *)sock_addr)->sin6_port);
            }
        }
    } else if (af == AF_UNIX) {
        struct sockaddr_un *un_addr = (struct sockaddr_un *)sock_addr;
        strncpy(ip_str, un_addr->sun_path, INET6_ADDRSTRLEN);
    } else {
        strncpy(ip_str, "unknown", INET6_ADDRSTRLEN);
    }

    if (ip_str[0] == '\0') {
        strncpy(ip_str, "<empty>", INET6_ADDRSTRLEN);
    }

    if (port > 0) {
        snprintf(addr, MAX_ADDR_STRLEN, "%s://%s:%d", c ? (c->transport == TRANSPORT_TCP ? "tcp" : "udp") : "unknown", ip_str, port);
    } else {
        snprintf(addr, MAX_ADDR_STRLEN, "%s://%s", c ? (c->transport == TRANSPORT_TCP ? "tcp" : "udp") : "unknown", ip_str);
    }
}

void format_connection_address(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    char ip[INET6_ADDRSTRLEN];
    int port = 0;
    char protocol[10];

    if (af == AF_INET) {
        struct sockaddr_in *saddr = (struct sockaddr_in *)sock_addr;
        if (inet_ntop(AF_INET, &(saddr->sin_addr), ip, INET6_ADDRSTRLEN) == NULL) {
            strncpy(ip, "[invalid]", sizeof(ip));
        }
        port = ntohs(saddr->sin_port);
        snprintf(protocol, sizeof(protocol), "TCP");
    } else if (af == AF_INET6) {
        struct sockaddr_in6 *saddr = (struct sockaddr_in6 *)sock_addr;
        if (inet_ntop(AF_INET6, &(saddr->sin6_addr), ip, INET6_ADDRSTRLEN) == NULL) {
            strncpy(ip, "[invalid]", sizeof(ip));
        }
        port = ntohs(saddr->sin6_port);
        snprintf(protocol, sizeof(protocol), "TCP");
    } else if (af == AF_UNIX) {
        struct sockaddr_un *saddr = (struct sockaddr_un *)sock_addr;
        strncpy(ip, saddr->sun_path, sizeof(ip));
        ip[sizeof(ip) - 1] = '\0'; // Ensure null-termination
        snprintf(protocol, sizeof(protocol), "UNIX");
    } else {
        strncpy(ip, "[unknown]", sizeof(ip));
        snprintf(protocol, sizeof(protocol), "UNKNOWN");
    }

    if (ip[0] == '\0') {
        strncpy(ip, "[none]", sizeof(ip));
    }

    if (af == AF_UNIX) {
        snprintf(addr, MAX_ADDRSTRLEN, "%s@%s", protocol, ip);
    } else {
        snprintf(addr, MAX_ADDRSTRLEN, "%s@%s:%d", protocol, ip, port);
    }
}

void format_socket_address(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    char ip[INET6_ADDRSTRLEN];
    int port = 0;

    if (af == AF_INET || af == AF_INET6) {
        inet_ntop(af, get_addr_ptr(af, sock_addr), ip, sizeof(ip));
        port = ntohs(get_port(af, sock_addr));
        if (port > 0) {
            snprintf(addr, MAX_ADDRSTRLEN, "%s://%s:%d", c->transport, ip, port);
        } else {
            snprintf(addr, MAX_ADDRSTRLEN, "%s://%s", c->transport, ip);
        }
    } else if (af == AF_UNIX) {
        struct sockaddr_un *unix_addr = (struct sockaddr_un *)sock_addr;
        if (strlen(unix_addr->sun_path) > 0) {
            snprintf(addr, MAX_ADDRSTRLEN, "%s://%s", c->transport, unix_addr->sun_path);
        } else {
            snprintf(addr, MAX_ADDRSTRLEN, "%s://<unknown>", c->transport);
        }
    } else {
        snprintf(addr, MAX_ADDRSTRLEN, "%s://<unknown>", c->transport);
    }
}
